from __future__ import annotations

from pathlib import Path

import typer
from rich.console import Console

from harness import __version__

app = typer.Typer(
    name="harness",
    help="Configuration-driven SDLC harness generator for Claude Code.",
    no_args_is_help=True,
    add_completion=False,
)

console = Console()
err_console = Console(stderr=True)

# Default config filename used by every command that reads the harness config.
_DEFAULT_CONFIG = Path("harness.yaml")


def _version_callback(value: bool) -> None:
    if value:
        console.print(f"harness {__version__}")
        raise typer.Exit()


@app.callback()
def main(
    version: bool = typer.Option(
        False,
        "--version",
        "-V",
        callback=_version_callback,
        is_eager=True,
        help="Show version and exit.",
    ),
) -> None:
    """Configuration-driven SDLC harness generator."""


@app.command()
def init(
    config: Path = typer.Option(
        _DEFAULT_CONFIG,
        "--config",
        "-c",
        help="Path to write the generated config (default: harness.yaml).",
    ),
    force: bool = typer.Option(False, "--force", help="Overwrite an existing config."),
    interactive: bool = typer.Option(
        False, "--interactive", "-i",
        help="Run the 10-prompt wizard instead of writing silent defaults.",
    ),
    target: str = typer.Option(
        None, "--target", "-t",
        help="Emitter target: claude-code (v1) | codex / copilot / gemini / cursor / antigravity (planned). "
             "If omitted, prompts when run interactively, else defaults to claude-code.",
    ),
    non_interactive: bool = typer.Option(
        False, "--non-interactive",
        help="(Deprecated; silent is the default.) Backwards-compat alias.",
        hidden=True,
    ),
) -> None:
    """Write harness.yaml. Silent by default (empty stacks + safe defaults).

    Add stacks / integrations / governance later via `harness add ...`.
    Pass `--interactive` to run the wizard.
    """
    from harness.commands.init import run_wizard

    code = run_wizard(
        config,
        force=force,
        interactive=interactive,
        non_interactive=non_interactive,
        target=target,
    )
    raise typer.Exit(code=code)


@app.command()
def generate(
    config: Path = typer.Option(
        _DEFAULT_CONFIG,
        "--config",
        "-c",
        help="Path to harness.yaml.",
    ),
    out_dir: Path = typer.Option(
        Path("."),
        "--out",
        "-o",
        help="Output directory (will write .claude/ inside).",
    ),
    target: str = typer.Option(
        None,
        "--target",
        "-t",
        help="Emitter target: claude-code (v1) | codex / copilot / gemini / cursor / antigravity (planned). "
             "If omitted, prompts when interactive, else defaults to claude-code.",
    ),
    dry_run: bool = typer.Option(False, "--dry-run", help="Print the plan, do not write."),
    diff: bool = typer.Option(False, "--diff", help="Show unified diff vs existing files."),
    legacy_commands: bool = typer.Option(
        False,
        "--legacy-commands",
        help="Also emit .claude/commands/<n>.md alongside skills (AD-mobile parity).",
    ),
) -> None:
    """Render harness from harness.yaml."""
    # Resolve target. If user passed --target explicitly, use it.
    # If --target absent and harness.yaml exists, defer the target decision to the yaml.
    # If --target absent and harness.yaml missing, prompt (TTY) or default claude-code.
    from harness.commands.init import (
        _SUPPORTED_TARGETS,
        _V1_TARGET,
        _print_target_unsupported,
        prompt_target,
    )
    from harness.compose.build_ir import compose_ir
    from harness.compose.layers import resolve_layers
    from harness.config.loader import ConfigError, load_config
    from harness.emitters.base import EmitOptions
    from harness.emitters.claude_code import ClaudeCodeEmitter
    if target is not None:
        if target not in _SUPPORTED_TARGETS:
            err_console.print(
                f"[red]Unknown target {target!r}. Valid: {_SUPPORTED_TARGETS}.[/red]"
            )
            raise typer.Exit(code=1)
        if target != _V1_TARGET:
            _print_target_unsupported(target)
            raise typer.Exit(code=1)

    # Auto-init: if harness.yaml is missing, write a silent default and continue.
    # User can customize later via `harness add stack | integration | governance`.
    if not config.exists():
        from harness.commands.init import run_wizard
        # Pick target now so auto-init can record it in the yaml.
        resolved_target = target or prompt_target()
        if resolved_target is None:
            raise typer.Exit(code=1)
        if resolved_target != _V1_TARGET:
            _print_target_unsupported(resolved_target)
            raise typer.Exit(code=1)
        console.print(
            f"[dim]{config} not found — writing silent default. "
            f"Customize later via [bold]harness add ...[/bold].[/dim]"
        )
        init_rc = run_wizard(
            config, force=False, interactive=False, target=resolved_target
        )
        if init_rc != 0:
            raise typer.Exit(code=init_rc)
        target = resolved_target
    else:
        # yaml present; target defaults to claude-code if not explicitly given.
        if target is None:
            target = _V1_TARGET

    try:
        cfg = load_config(config)
    except ConfigError as e:
        err_console.print(f"[red]config error:[/red] {e}")
        raise typer.Exit(code=1) from e

    overrides = config.parent / ".harness" / "overrides"
    layers = resolve_layers(cfg, project_overrides_dir=overrides)
    ir = compose_ir(cfg, layers)

    emitter = ClaudeCodeEmitter()
    opts = EmitOptions(out_dir=out_dir, dry_run=dry_run, diff=diff, legacy_commands=legacy_commands, config=cfg)
    result = emitter.emit(ir, opts)

    written = len(result.write.written)
    unchanged = len(result.write.unchanged)
    skipped = len(result.write.skipped_dry_run)
    preserved = len(result.write.preserved)
    preserved_suffix = f"; {preserved} team-owned (CLAUDE.md / *-patterns) preserved" if preserved else ""

    if dry_run:
        console.print(
            f"[yellow]DRY RUN[/yellow] would write {skipped} file(s); {unchanged} unchanged{preserved_suffix}"
        )
    else:
        console.print(f"wrote {written} file(s); {unchanged} unchanged{preserved_suffix}")

    if diff and result.write.diffs:
        for path, diff_text in result.write.diffs.items():
            console.print(f"\n[cyan]── {path} ──[/cyan]")
            console.print(diff_text)

    if result.warnings:
        for w in result.warnings:
            err_console.print(f"[yellow]warn[/yellow] {w}")


@app.command()
def validate(
    config: Path = typer.Option(
        _DEFAULT_CONFIG,
        "--config",
        "-c",
        help="Path to harness.yaml.",
    ),
    out_dir: Path = typer.Option(
        Path("."), "--out", "-o", help="Output directory containing .claude/ to lint."
    ),
    strict: bool = typer.Option(False, "--strict", help="Treat warnings as errors."),
) -> None:
    """Schema-check config and lint emitted output."""
    from harness.config.loader import ConfigError, load_config
    from harness.validators.output_lint import lint_output

    try:
        load_config(config)
        console.print(f"[green]config OK[/green] {config}")
    except ConfigError as e:
        err_console.print(f"[red]config error:[/red] {e}")
        raise typer.Exit(code=1) from e

    if not (out_dir / ".claude").is_dir():
        console.print(f"[yellow]no .claude/ at {out_dir}; skipping output lint.[/yellow]")
        return

    report = lint_output(out_dir)
    for f in report.findings:
        style = "red" if f.severity == "error" else "yellow"
        err_console.print(f"[{style}]{f.format()}[/{style}]")

    n_err = len(report.errors())
    n_warn = len(report.warnings())
    summary = f"{n_err} error(s), {n_warn} warning(s)"
    if report.passed(strict=strict):
        console.print(f"[green]lint passed[/green] {summary}")
    else:
        err_console.print(f"[red]lint failed[/red] {summary}")
        raise typer.Exit(code=1)


