@list_app.command("todos")
def list_todos(
    out_dir: Path = typer.Option(Path("."), "--out", "-o"),
) -> None:
    """Report N files with K open TODO slots, grouped by layer."""
    from harness.validators.output_lint import lint_output

    if not (out_dir / ".claude").is_dir():
        err_console.print(f"[red]no .claude/ at {out_dir}[/red]")
        raise typer.Exit(code=1)

    report = lint_output(out_dir)
    todos = [f for f in report.findings if f.rule == "F-013"]
    if not todos:
        console.print("[green]no TODO slots remain[/green]")
        return

    total = 0
    for f in todos:
        # message is "N TODO slot(s) unfilled"; pull N
        count = int(f.message.split()[0])
        total += count
        rel = f.file.relative_to(out_dir) if out_dir in f.file.parents else f.file
        console.print(f"  [yellow]{count}[/yellow]  {rel}")
    console.print(f"\n[bold]{total}[/bold] TODO slot(s) across {len(todos)} file(s)")


@app.command()
def audit(
    out_dir: Path = typer.Option(Path("."), "--out", "-o"),
    strict: bool = typer.Option(False, "--strict", help="Treat warnings (incl. F-013 TODOs) as errors."),
) -> None:
    """Governance check on emitted output. With --strict, unfilled TODO slots fail."""
    from harness.validators.output_lint import lint_output

    if not (out_dir / ".claude").is_dir():
        err_console.print(f"[red]no .claude/ at {out_dir}[/red]")
        raise typer.Exit(code=1)

    report = lint_output(out_dir)
    governance_rules = {"F-005", "F-007", "F-008", "F-010", "F-038", "F-039"}
    governance_findings = [f for f in report.findings if f.rule in governance_rules]
    todo_findings = [f for f in report.findings if f.rule == "F-013"]

    for f in governance_findings:
        err_console.print(f"[red]{f.format()}[/red]")
    for f in todo_findings:
        style = "red" if strict else "yellow"
        err_console.print(f"[{style}]{f.format()}[/{style}]")

    fail = bool([f for f in governance_findings if f.severity == "error"])
    if strict and todo_findings:
        fail = True

    if fail:
        err_console.print("[red]audit failed[/red]")
        raise typer.Exit(code=1)
    console.print(
        f"[green]audit passed[/green] governance:{len(governance_findings)} "
        f"todos:{len(todo_findings)}"
    )


@app.command()
def analyse(
    project: str = typer.Option(
        None, "--project", "-p",
        help="Project path/slug (default: derive from cwd).",
    ),
    session: str = typer.Option(None, "--session", "-s", help="Session id (or prefix)."),
    latest: bool = typer.Option(False, "--latest", help="Use the most recent session."),
    all_sessions: bool = typer.Option(
        False, "--all",
        help="Stitch every session in the project into one chronological timeline. "
             "Mutually exclusive with --session and --latest.",
    ),
    out_dir: Path = typer.Option(Path("harness-reports"), "--out", "-o"),
    format: str = typer.Option("html", "--format", "-f", help="html|json|md|all"),
    skip_synthesis: bool = typer.Option(
        False, "--no-llm",
        help="Skip Claude CLI narrative synthesis; emit static metrics only.",
    ),
    model: str = typer.Option(
        "sonnet", "--model", "-m",
        help="Model passed to `claude --print` for synthesis.",
    ),
    list_projects_flag: bool = typer.Option(False, "--list-projects"),
    list_sessions_flag: bool = typer.Option(False, "--list-sessions"),
    watch: bool = typer.Option(
        False, "--watch", "-w",
        help="Live dashboard mode. Polls JSONL mtime and re-renders on change.",
    ),
    watch_interval: int = typer.Option(
        5, "--watch-interval",
        help="Polling interval in seconds for --watch (clamped to [1, 60]).",
    ),
    watch_synth: bool = typer.Option(
        False, "--watch-synth",
        help="Run narrative LLM synthesis on every --watch tick (slow; default off).",
    ),
) -> None:
    """Read Claude Code session JSONL and emit a timeline report."""
    from harness.commands.analyse import (
        cmd_analyse,
        cmd_list_projects,
        cmd_list_sessions,
        cmd_watch,
    )

    if list_projects_flag:
        raise typer.Exit(code=cmd_list_projects())
    if list_sessions_flag:
        if not project:
            err_console.print("[red]--list-sessions requires --project[/red]")
            raise typer.Exit(code=1)
        raise typer.Exit(code=cmd_list_sessions(project))

    if watch:
        # Under --watch, default to skipping synthesis (too slow per tick)
        # unless the user explicitly opts in via --watch-synth.
        effective_skip = skip_synthesis or not watch_synth
        raise typer.Exit(code=cmd_watch(
            project=project,
            session=session,
            latest=latest,
            out_dir=out_dir,
            format=format,
            skip_synthesis=effective_skip,
            model=model,
            interval_seconds=watch_interval,
        ))

    raise typer.Exit(code=cmd_analyse(
        project=project,
        session=session,
        latest=latest,
        all_sessions=all_sessions,
        out_dir=out_dir,
        format=format,
        skip_synthesis=skip_synthesis,
        model=model,
    ))


