@app.command()
def tune(
    project: str = typer.Option(
        None, "--project", "-p",
        help="Project path/slug (default: derive from cwd).",
    ),
    last: int = typer.Option(
        5, "--last", "-n",
        help="Number of most-recent sessions to aggregate.",
    ),
    out_path: Path = typer.Option(
        None, "--out", "-o",
        help="Where to write the tuning report. Defaults to docs/tuning/tuning-<TIMESTAMP>.md.",
    ),
    threshold_interventions: float = typer.Option(
        2.0, "--threshold-interventions",
        help="Flag commands whose mean interventions/run ≥ this value.",
    ),
    threshold_intervention_rate: float = typer.Option(
        0.5, "--threshold-intervention-rate",
        help="Flag commands whose intervention rate ≥ this fraction (0.0-1.0).",
    ),
    threshold_blocked: float = typer.Option(
        0.2, "--threshold-blocked",
        help="Flag commands whose blocked-signal rate ≥ this fraction (0.0-1.0).",
    ),
) -> None:
    """Friction analysis across recent Claude Code sessions → tuning report."""
    from harness.commands.tune import cmd_tune
    if out_path is None:
        from datetime import datetime
        ts = datetime.now().strftime("%Y%m%d-%H%M")
        out_path = Path("docs/tuning") / f"tuning-{ts}.md"
    raise typer.Exit(code=cmd_tune(
        project=project,
        last=last,
        out_path=out_path,
        threshold_interventions=threshold_interventions,
        threshold_blocked=threshold_blocked,
        threshold_intervention_rate=threshold_intervention_rate,
    ))


