@app.command()
def fill(
    skill_name: str = typer.Argument(
        None,
        help="`<framework>-patterns` skill to fill (e.g. nextjs-patterns). Omit when --all.",
    ),
    all_patterns: bool = typer.Option(
        False, "--all", help="Fill every `<framework>-patterns` skill with unfilled TODOs.",
    ),
    yes: bool = typer.Option(
        False, "--yes", "-y", help="Skip the confirm prompt before writing.",
    ),
    dry_run: bool = typer.Option(
        False, "--dry-run", help="Invoke claude + show diff but never write.",
    ),
    project_dir: Path = typer.Option(
        Path(".claude"), "--project-dir", help="Path to .claude/.",
    ),
    config: Path = typer.Option(
        _DEFAULT_CONFIG, "--config", "-c",
        help="Path to harness.yaml.",
    ),
) -> None:
    """Fill the TODO slots in `*-patterns` skill bodies via local `claude` CLI.

    Harness owns the slot structure; Claude fills the content within those slots.
    Frontmatter is preserved verbatim. Body kept ≤ 150 lines per the prompt
    contract. Run after `harness add stack <name>:<version>` (which emits the
    scaffold with TODOs) and before `/arh-plan-implementation` (which reads the
    filled body).
    """
    from harness.commands.fill import cmd_fill
    raise typer.Exit(code=cmd_fill(
        skill_name=skill_name,
        all_patterns=all_patterns,
        yes=yes,
        dry_run=dry_run,
        project_dir=project_dir,
        config_path=config,
    ))


